import math
from qiskit import QuantumCircuit, QuantumRegister


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _parse(instance):
    if not isinstance(instance, dict):
        raise ValueError('instance must be a dict')
    n = instance.get('n')
    d = instance.get('d')
    mons = instance.get('monomials')
    a = instance.get('direction')
    if not _is_int(n) or n < 1 or n > 12:
        raise ValueError('n must be an integer in [1,12]')
    if not _is_int(d) or d < 1 or d > n:
        raise ValueError('d must be an integer in [1,n]')
    if not isinstance(mons, list):
        raise ValueError('monomials must be a list of index lists')
    if not _is_int(a) or a < 0 or a >= 2 ** n:
        raise ValueError('direction must be an integer mask in [0,2^n)')
    parity = {}
    for m in mons:
        if not isinstance(m, list):
            raise ValueError('each monomial must be a list of variable indices')
        for idx in m:
            if not _is_int(idx) or idx < 0 or idx >= n:
                raise ValueError('variable index out of range')
        if len(set(m)) != len(m):
            raise ValueError('multilinear monomials cannot repeat a variable')
        if len(m) > d:
            raise ValueError('monomial degree exceeds d')
        key = tuple(sorted(m))
        parity[key] = parity.get(key, 0) ^ 1
    active = [k for k in parity if parity[k] == 1]
    active.sort(key=lambda k: (len(k), k))
    return n, a, active


def _apply_phase_oracle(qc, active):
    # eq_1 / eq_2: O_f|x> = (-1)^f(x)|x>; each monomial with c_S=1 gives a Z-type phase on the qubits in S
    for S in active:
        if len(S) == 0:
            qc.global_phase = qc.global_phase + math.pi
        elif len(S) == 1:
            qc.z(S[0])
        elif len(S) == 2:
            qc.cz(S[0], S[1])
        else:
            qc.mcp(math.pi, list(S[:-1]), S[-1])


def build_circuit(instance):
    n, a, active = _parse(instance)
    qc = QuantumCircuit(QuantumRegister(n, 'x'))
    # eq_3: first Hadamard layer
    qc.h(range(n))
    # eq_2: phase oracle O_f
    _apply_phase_oracle(qc, active)
    if a:
        # eq_5: O_{D_a f} = O_f (X^a O_f X^a)
        bits = [i for i in range(n) if (a >> i) & 1]
        for i in bits:
            qc.x(i)
        _apply_phase_oracle(qc, active)
        for i in bits:
            qc.x(i)
    # eq_3: final Hadamard layer
    qc.h(range(n))
    return qc

from qiskit import QuantumCircuit, QuantumRegister


def _parse(instance):
    if not isinstance(instance, dict):
        raise ValueError('instance must be a dict')
    n = instance.get('n')
    d = instance.get('d')
    if isinstance(n, bool) or not isinstance(n, int) or n < 1 or n > 3:
        raise ValueError('n must be an integer in 1..3')
    if isinstance(d, bool) or not isinstance(d, int) or d < 1 or d > 2:
        raise ValueError('d must be 1 or 2')
    coeffs = instance.get('coefficients')
    if not isinstance(coeffs, dict):
        raise ValueError('coefficients must be a dict')
    mons = {}
    for key, val in coeffs.items():
        if not isinstance(key, str) or key == '':
            raise ValueError('bad coefficient key')
        if isinstance(val, bool):
            val = int(val)
        if val not in (0, 1) or not isinstance(val, int):
            raise ValueError('coefficients must be 0 or 1')
        if key == '0':
            S = ()
        else:
            if not key.isdigit():
                raise ValueError('bad coefficient key')
            S = tuple(int(ch) for ch in key)
            if len(S) > d:
                if val:
                    raise ValueError('monomial degree exceeds d')
            for a, b in zip(S, S[1:]):
                if a >= b:
                    raise ValueError('monomial indices must be strictly increasing')
            if any(j < 1 or j > n for j in S):
                raise ValueError('variable index out of range')
        if S in mons:
            raise ValueError('duplicate key')
        mons[S] = val
    return n, d, mons


def _phase(qc, qs):
    # multi-controlled Z on the listed qubits (phase -1 iff all are 1)
    k = len(qs)
    if k == 1:
        qc.z(qs[0])
    elif k == 2:
        qc.cz(qs[0], qs[1])
    elif k == 3:
        qc.ccz(qs[0], qs[1], qs[2])
    else:
        raise ValueError('unsupported monomial size')


def _restricted_oracle(qc, ctrl, qmap, mons, i, val):
    # eq_2: controlled phase oracle C-O_f with x_i fixed to val (val in {0,1});
    # each monomial prod_{j in S} x_j becomes a (multi-)controlled Z.
    for S, c in mons.items():
        if not c:
            continue
        if i in S:
            if val == 0:
                continue
            rest = [j for j in S if j != i]
        else:
            rest = list(S)
        _phase(qc, [ctrl] + [qmap[j] for j in rest])


def build_circuit(instance):
    """Derivative-BV identification of a multilinear F_2 polynomial (n<=3, d<=2).

    Layout: block i (1..n) occupies qubits (i-1)*n .. i*n-1: first the ancilla a_i,
    then the variables j != i ascending. Final qubit n*n is a0.
    """
    n, d, mons = _parse(instance)
    nq = n * n + 1
    if nq > 12:
        raise ValueError('too many qubits')
    qr = QuantumRegister(nq, 'q')
    qc = QuantumCircuit(qr)
    a0 = n * n
    blocks = []
    for i in range(1, n + 1):
        base = (i - 1) * n
        others = [j for j in range(1, n + 1) if j != i]
        qmap = {j: base + 1 + others.index(j) for j in others}
        blocks.append((i, base, qmap))
    # input layer: H on ancillas and x registers
    for i, base, qmap in blocks:
        qc.h(base)
        for q in qmap.values():
            qc.h(q)
    qc.h(a0)
    # eq_3/eq_4: derivative phase (-1)^{b D_i f(x)} = C-O_f(x_i=1) * C-O_f(x_i=0)
    for i, base, qmap in blocks:
        _restricted_oracle(qc, base, qmap, mons, i, 1)
        _restricted_oracle(qc, base, qmap, mons, i, 0)
    # eq_5: C-O_f on fixed |0..0> gives phase (-1)^{b c_0} on the control only
    if mons.get((), 0):
        qc.z(a0)
    # output layer
    for i, base, qmap in blocks:
        qc.h(base)
        for q in qmap.values():
            qc.h(q)
    qc.h(a0)
    return qc

from qiskit import QuantumCircuit

_KEYS = ("0", "1", "2", "3", "12", "13", "23")


def _read_coefficients(instance):
    if not isinstance(instance, dict):
        raise ValueError("instance must be a dict")
    for k in instance:
        if k not in ("coefficients", "n", "d", "q"):
            raise ValueError("unknown instance key: %r" % (k,))
    if instance.get("n", 3) != 3 or instance.get("d", 2) != 2 or instance.get("q", 2) != 2:
        raise ValueError("only n=3, d=2, q=2 is supported")
    raw = instance.get("coefficients", {})
    if not isinstance(raw, dict):
        raise ValueError("coefficients must be a dict")
    coeffs = {k: 0 for k in _KEYS}
    for key, val in raw.items():
        if key not in coeffs:
            raise ValueError("invalid monomial key: %r" % (key,))
        if isinstance(val, bool):
            val = int(val)
        if not isinstance(val, int) or val not in (0, 1):
            raise ValueError("coefficients must be 0 or 1")
        coeffs[key] = val
    return coeffs


def build_circuit(instance):
    """Qubits: 0=a0 (c_0); 1,2,3=a1..a3 (c_1..c_3); (4,5)=(x2,x3) block 1;
    (6,7)=(x1,x3) block 2; (8,9)=(x1,x2) block 3.
    Output basis state: q0=c_0,q1..q3=c_i, block qubit for partner j of i = c_ij."""
    c = _read_coefficients(instance)
    qc = QuantumCircuit(10)
    # eq_4: first Hadamard layer
    for q in range(10):
        qc.h(q)
    # eq_5: constant term
    if c["0"]:
        qc.z(0)
    # eq_2/eq_3: derivative phase (-1)^(c_i*b + l.x') as uncontrolled Z gates
    for i in (1, 2, 3):
        if c[str(i)]:
            qc.z(i)
        base = 2 + 2 * i
        others = [j for j in (1, 2, 3) if j != i]
        for k, j in enumerate(others):
            key = str(min(i, j)) + str(max(i, j))
            if c[key]:
                qc.z(base + k)
    # eq_4: final Hadamard layer
    for q in range(10):
        qc.h(q)
    return qc
